/**
 * School-connection contract dependency record. Tasks: L-O-01, L-O-02.
 *
 * STATUS: BLOCKED. No connect contract, no QR-payload contract, no storage contract.
 * The School Dashboard states `QR secure backend se generate hoga` (QR is generated by
 * the secure backend), and `connectSchool()` in the mobile reference is explicitly a
 * demo (`in this demo`). Nothing here establishes a session or persists a school.
 *
 * Re-check 2026-10-18: migration 000007 (C-K-02) added a UNIQUE `schools.school_code`
 * column (VARCHAR 50, nullable) and `docs/provisioning-state-machine.md` documents the
 * rules (3-50 chars, alphanumeric + hyphens/underscores, no PII, uniqueness enforced at
 * database level). So the COLUMN exists. What is still missing is the SEMANTICS: no
 * published payload format, no signature, no expiry, no revocation and no endpoint that
 * accepts or returns a code. `connectSchool()` is still explicitly `in this demo`.
 */

import { ReportContractStatus } from '../../reports/contracts/pending-report-contract.js';

export const ConnectionContractStatus = ReportContractStatus;

/**
 * Whether the connection-adjacent schema exists. True since migration 000007,
 * because `schools.school_code` is a real column. This is NOT the same as a
 * connection contract: the column has no published semantics and no endpoint.
 */
export const CONNECTION_SCHEMA_PUBLISHED = true;

/** Entities Batch L needs before a real connection can be bound. */
export const MISSING_CONNECTION_ENTITIES = Object.freeze([
  Object.freeze({ entity: 'school_connection_sessions', need: 'Connected school, actor, connected-at, cleared-at' }),
  Object.freeze({ entity: 'qr_payloads', need: 'QR payload shape, expiry and signature (Batch C blocker)' }),
  Object.freeze({ entity: 'connect_endpoints', need: 'POST /connect or equivalent accepting domain + code, returning the connected school' }),
]);

/** @type {ReadonlyArray<Readonly<object>>} */
export const PENDING_CONNECTION_CONTRACTS = Object.freeze([
  Object.freeze({
    id: 'school-connection',
    capability: 'connect a school by QR scan or manual domain/code',
    status: ConnectionContractStatus.BLOCKED_NEEDS_PROVISIONING,
    method: null,
    path: null,
    requestSchema: null,
    responseSchema: null,
    implemented: false,
    blocker:
      'No endpoint. The QR is `secure backend se generate hoga` and `connectSchool()` is ' +
      'explicitly `in this demo`. The transcribed validation (`domain` + `code` required,' +
      ' name derived from domain) is all that exists.',
    unblockRequires:
      'KiloCode publishes the connect contract: domain/code validation, QR payload ' +
      'verification, the connected-school response, and server-side tenant resolution.',
  }),
  Object.freeze({
    id: 'school-selection-persistence',
    capability: 'persist and clear the selected school on logout/switch',
    status: ConnectionContractStatus.BLOCKED_NOT_CONTRACTED,
    method: null,
    path: null,
    requestSchema: null,
    responseSchema: null,
    implemented: false,
    blocker:
      'No storage contract. The reference writes no browser storage for the connection, ' +
      'and Batch B already bans every storage primitive absolutely, so nothing may persist.',
    unblockRequires:
      'The owner approves an exact storage scope (L-O-04 adjacent), then KiloCode ' +
      'publishes the persistence contract. Until then `selectedSchool()` is in-memory ' +
      'and `clearSelectedSchool()` clears it.',
  }),
]);

/** No connection or persistence request may be made. */
export const CONNECTION_INTEGRATION_AUTHORIZED = false;

export function assertNoInventedConnectionSchemas(contracts = PENDING_CONNECTION_CONTRACTS) {
  if (CONNECTION_INTEGRATION_AUTHORIZED) {
    throw new Error('connection integration is authorized without a published contract');
  }
  for (const contract of contracts) {
    for (const field of ['method', 'path', 'requestSchema', 'responseSchema']) {
      if (contract[field] !== null) {
        throw new Error(`connection contract '${contract.id}' declares ${field} without a contract`);
      }
    }
    if (contract.implemented !== false) {
      throw new Error(`connection contract '${contract.id}' claims implementation without an endpoint`);
    }
    if (contract.status === ConnectionContractStatus.PUBLISHED) {
      throw new Error(`connection contract '${contract.id}' claims to be published; update this module`);
    }
  }
  return true;
}

export function findPendingConnectionContract(id) {
  return PENDING_CONNECTION_CONTRACTS.find((contract) => contract.id === id) ?? null;
}

export function describeConnectionBlock() {
  return {
    schemaPublished: CONNECTION_SCHEMA_PUBLISHED,
    integrationAuthorized: CONNECTION_INTEGRATION_AUTHORIZED,
    missingEntities: MISSING_CONNECTION_ENTITIES.length,
    capabilities: PENDING_CONNECTION_CONTRACTS.map((contract) => ({
      id: contract.id,
      status: contract.status,
    })),
  };
}
